sp_widget.client_script:
api.controller = function(spUtil) {

	var c = this;

	spUtil.get("widget_gauge").then(function(response) {
			c.widget_gauge = response;
	});

	spUtil.get("widget-cool-clock").then(function(response) {
            c.myClockWidget = response;
    });


	// Widgets individuais
	spUtil.get("widget_limite_com_despesas_filtro").then(function (response) {
		c.widget_gauge_filtro = response;
	});
	spUtil.get("widget_limite_com_despesas_semidonut").then(function (response) {
		c.widget_semidonut = response;
	});
	spUtil.get("widget_despesa_comprometimento").then(function (response) {
		c.widget_comprometimento = response;
	});
	spUtil.get("widget_despesas_porcentagem_ano").then(function (response) {
		c.widget_porcentagem = response;
	});
	spUtil.get("widget_despesa_line_bar_v2").then(function (response) {
		c.widget_grafico_barra = response;
	});




}

sp_widget.css:
.container2 {
  background-color: white;
  border: 2px solid #ccc;
  border-radius: 12px;
  padding: 1rem;
  //max-width: 1200px;
  //margin: auto;

  margin-top: 20rem;
}

.top-row {
  display: flex;
  gap: 1rem;
  max-height: 500px;
  height: 500px;
  overflow: hidden; /* ou auto se quiser rolagem */
  margin-bottom: 1rem;
}


.top-row .widget,
.top-row .col-vertical {
  flex: 1;
  height: 100%;
  box-sizing: border-box;
}
.col-vertical {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  height: 100%;
}
.col-vertical {
    max-width: 19rem;
}

.col-vertical .widget {
  flex: 1;
}

.container2 {
  background-color: white;
  border: 2px solid #ccc;
  border-radius: 12px;
  padding: 1rem;
  overflow: hidden; /* Impede estouros do container */
}

.top-row {
  display: flex;
  gap: 1rem;
  max-height: 500px;
  height: 500px;
  overflow: hidden; /* Garante que nada ultrapasse */
  margin-bottom: 1rem;
}

.top-row .widget,
.top-row .col-vertical {
  flex: 1;
  height: 100%;
  box-sizing: border-box;
}

.col-vertical {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  height: 100%;
}

.col-vertical .widget {
  flex: 1;
  overflow: hidden;
}

.widget {
  background-color: #e0ffe0;
  border: 1px solid #aaa;
  border-radius: 12px;
  padding: 1rem;
  text-align: center;
  box-sizing: border-box;
  height: 100%; /* ajuda a controlar o crescimento */
}

.widget.wide {
  width: 100%;
  margin-top: 1rem;
  background-color: #fff0c2;
}


/* 📱 Responsivo para telas menores */
@media (max-width: 768px) {
  .top-row {
    flex-direction: column;
    height: auto;
    max-height: none;
  }

  .col-vertical {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .col-vertical .widget {
    flex: 1 1 100%;
  }

  .header {
    flex-direction: column;
  }
}

img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 0 auto;
}




.widget.wide {
  max-height: 400px;
  overflow: auto; /* permite rolagem se o conteúdo ultrapassar */
}
